//! Typed output: the conversion of the output of a validator into Rust types,
//! for the types generated by `livr::schema!`.

use std::collections::BTreeMap;
use std::fmt;

use serde_json::{Map, Value};

use crate::error::{ErrorTree, Errors};
use crate::util::is_no_value;
use crate::validator::Validator;

/// A type built from the output of a validator. Empty values (missing,
/// `null`, `""`) of optional fields are `None`.
pub trait FromLivr: Sized {
    /// Builds the value from the output.
    ///
    /// # Errors
    ///
    /// A [`ConvertError`] when the output does not fit the type.
    fn from_livr(value: Value) -> Result<Self, ConvertError>;
}

/// A type built from the output of a validator, from a reference: values are
/// copied. Used for values that the rules do not change.
pub trait FromLivrRef: Sized {
    /// Builds the value from the output.
    ///
    /// # Errors
    ///
    /// A [`ConvertError`] when the output does not fit the type.
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError>;
}

/// An object type that validates its fields itself: the types of
/// `livr::schema!`. The output is built without an intermediate map.
///
/// Not part of the public API: implemented by the code of `schema!`.
#[doc(hidden)]
pub trait TypedObject: Sized {
    /// Validates the fields of an object.
    ///
    /// # Errors
    ///
    /// The errors of the invalid fields.
    fn validate_fields(data: &Map<String, Value>) -> Result<Self, BTreeMap<String, ErrorTree>>;

    /// Validates the fields of an owned object: values are moved.
    ///
    /// # Errors
    ///
    /// The errors of the invalid fields.
    fn validate_fields_owned(data: Map<String, Value>)
    -> Result<Self, BTreeMap<String, ErrorTree>>;
}

/// A schema with a typed output: the main type of `livr::schema!`. Code
/// generic over schemas, like the extractors of livr-axum, uses it.
///
/// `schema!` implements it; implementing it by hand is possible, but new
/// items may be added before 1.0.
pub trait Schema: Sized {
    /// The LIVR schema, as JSON: for a frontend that validates with the same
    /// rules. Custom rules and aliases are not in it.
    const SCHEMA: &'static str;

    /// The fields of the output, in the order of the schema: their names in
    /// the data and whether they are lists. Fields with an empty list of
    /// rules are not in the output, so they are not here either.
    ///
    /// For code that prepares data before validation, like the extractors of
    /// livr-axum: a query string or a form has no lists, so `?tags=a` must
    /// become `["a"]` for a list field, and keys that are not fields can be
    /// dropped early.
    const FIELDS: &'static [SchemaField];

    /// The validator of the schema, for an output that is not typed.
    fn validator() -> &'static Validator;

    /// Validates the data.
    ///
    /// # Errors
    ///
    /// The errors of the invalid fields, or `FORMAT_ERROR` when the data is
    /// not an object.
    fn validate(data: &Value) -> Result<Self, Errors>;

    /// Validates owned data, like data just parsed: values are moved instead
    /// of copied.
    ///
    /// # Errors
    ///
    /// The errors of the invalid fields, or `FORMAT_ERROR` when the data is
    /// not an object.
    fn validate_owned(data: Value) -> Result<Self, Errors>;
}

/// A field of a [`Schema`]: see [`Schema::FIELDS`].
///
/// `schema!` generates them; the documentation of `livr::schema!` has an
/// example.
///
/// ```
/// use livr_core::SchemaField;
///
/// let field = SchemaField::new("tags", true);
/// assert_eq!((field.name(), field.is_list()), ("tags", true));
/// ```
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct SchemaField {
    name: &'static str,
    is_list: bool,
}

impl SchemaField {
    /// A field with its name in the data, and whether it is a list.
    #[must_use]
    pub const fn new(name: &'static str, is_list: bool) -> Self {
        Self { name, is_list }
    }

    /// The name of the field in the data (the key of the schema, not the
    /// name of the Rust field).
    #[must_use]
    pub const fn name(&self) -> &'static str {
        self.name
    }

    /// Whether the field is a list: its type is `Vec<_>` or `Option<Vec<_>>`,
    /// as inferred from the built-in rules (`list_of`, `list_of_objects`,
    /// `list_of_different_objects`, `not_empty_list`). The output type of a
    /// custom rule does not count.
    #[must_use]
    pub const fn is_list(&self) -> bool {
        self.is_list
    }
}

/// A part of the path of a value in the data.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PathSegment {
    /// A field of an object, by name.
    Field(String),
    /// An item of a list, by index.
    Index(usize),
}

/// The output does not fit the type. It does not happen for the types of
/// `livr::schema!`, unless a custom rule outputs another type than the one it
/// declares.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ConvertError {
    expected: &'static str,
    // From the value up to the data
    path: Vec<PathSegment>,
}

impl ConvertError {
    /// The output is not a value of the expected type.
    #[must_use]
    pub fn new(expected: &'static str) -> Self {
        Self {
            expected,
            path: Vec::new(),
        }
    }

    /// The error of a field of an object.
    #[must_use]
    pub fn in_field(mut self, name: &str) -> Self {
        self.path.push(PathSegment::Field(name.to_owned()));
        self
    }

    /// The error of an item of a list.
    #[must_use]
    pub fn in_item(mut self, index: usize) -> Self {
        self.path.push(PathSegment::Index(index));
        self
    }

    /// The path of the value, from the data.
    pub fn path(&self) -> impl Iterator<Item = &PathSegment> {
        self.path.iter().rev()
    }

    /// The error as validation errors: `FORMAT_ERROR` at the path of the
    /// value.
    #[must_use]
    pub fn into_errors(self) -> Errors {
        let mut tree = ErrorTree::code("FORMAT_ERROR");
        let mut path = self.path.into_iter();
        let mut top = None;
        for segment in path.by_ref() {
            match segment {
                PathSegment::Field(name) => {
                    top = Some(name.clone());
                    tree = ErrorTree::Object(BTreeMap::from([(name, tree)]));
                }
                PathSegment::Index(index) => {
                    top = None;
                    let mut items = vec![None; index + 1];
                    items[index] = Some(tree);
                    tree = ErrorTree::List(items);
                }
            }
        }
        match (tree, top) {
            (ErrorTree::Object(fields), Some(_)) => Errors::Fields(fields),
            _ => Errors::Format,
        }
    }
}

impl fmt::Display for ConvertError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "expected {} at ", self.expected)?;
        for segment in self.path() {
            match segment {
                PathSegment::Field(name) => write!(f, "/{name}")?,
                PathSegment::Index(index) => write!(f, "/{index}")?,
            }
        }
        Ok(())
    }
}

impl std::error::Error for ConvertError {}

impl FromLivr for Value {
    #[inline]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        Ok(value)
    }
}

impl FromLivr for String {
    #[inline]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        match value {
            Value::String(str) => Ok(str),
            _ => Err(ConvertError::new("a string")),
        }
    }
}

impl FromLivr for i64 {
    #[inline]
    #[allow(clippy::cast_possible_truncation)]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        match &value {
            Value::Number(number) => match number.as_i64() {
                Some(int) => Ok(int),
                None => match number.as_f64() {
                    Some(float)
                        if float.fract() == 0.0 && float.abs() <= 9_007_199_254_740_992.0 =>
                    {
                        Ok(float as i64)
                    }
                    _ => Err(ConvertError::new("an integer")),
                },
            },
            _ => Err(ConvertError::new("an integer")),
        }
    }
}

impl FromLivr for f64 {
    #[inline]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        value.as_f64().ok_or_else(|| ConvertError::new("a number"))
    }
}

impl FromLivr for bool {
    #[inline]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        value
            .as_bool()
            .ok_or_else(|| ConvertError::new("a boolean"))
    }
}

impl FromLivr for Map<String, Value> {
    #[inline]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        match value {
            Value::Object(fields) => Ok(fields),
            _ => Err(ConvertError::new("an object")),
        }
    }
}

impl<T: FromLivr> FromLivr for Option<T> {
    #[inline]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        if is_no_value(&value) {
            Ok(None)
        } else {
            T::from_livr(value).map(Some)
        }
    }
}

impl<T: FromLivr> FromLivr for Vec<T> {
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        match value {
            Value::Array(items) => items
                .into_iter()
                .enumerate()
                .map(|(i, item)| T::from_livr(item).map_err(|error| error.in_item(i)))
                .collect(),
            _ => Err(ConvertError::new("a list")),
        }
    }
}

impl<T: FromLivr> FromLivr for Box<T> {
    #[inline]
    fn from_livr(value: Value) -> Result<Self, ConvertError> {
        T::from_livr(value).map(Box::new)
    }
}

impl FromLivrRef for Value {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        Ok(value.clone())
    }
}

impl FromLivrRef for String {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        match value {
            Value::String(str) => Ok(str.clone()),
            _ => Err(ConvertError::new("a string")),
        }
    }
}

impl FromLivrRef for i64 {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        match value {
            Value::Number(number) if number.is_i64() => Ok(number.as_i64().unwrap_or_default()),
            _ => Self::from_livr(value.clone()),
        }
    }
}

impl FromLivrRef for f64 {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        value.as_f64().ok_or_else(|| ConvertError::new("a number"))
    }
}

impl FromLivrRef for bool {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        value
            .as_bool()
            .ok_or_else(|| ConvertError::new("a boolean"))
    }
}

impl FromLivrRef for Map<String, Value> {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        match value {
            Value::Object(fields) => Ok(fields.clone()),
            _ => Err(ConvertError::new("an object")),
        }
    }
}

impl<T: FromLivrRef> FromLivrRef for Option<T> {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        if is_no_value(value) {
            Ok(None)
        } else {
            T::from_livr_ref(value).map(Some)
        }
    }
}

impl<T: FromLivrRef> FromLivrRef for Vec<T> {
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        match value {
            Value::Array(items) => items
                .iter()
                .enumerate()
                .map(|(i, item)| T::from_livr_ref(item).map_err(|error| error.in_item(i)))
                .collect(),
            _ => Err(ConvertError::new("a list")),
        }
    }
}

impl<T: FromLivrRef> FromLivrRef for Box<T> {
    #[inline]
    fn from_livr_ref(value: &Value) -> Result<Self, ConvertError> {
        T::from_livr_ref(value).map(Box::new)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn converts_values() {
        assert_eq!(Option::<i64>::from_livr(json!("")), Ok(None));
        assert_eq!(Option::<i64>::from_livr(json!(5)), Ok(Some(5)));
        assert_eq!(
            Vec::<Option<String>>::from_livr(json!(["a", null])),
            Ok(vec![Some("a".into()), None])
        );
        assert_eq!(i64::from_livr(json!(5.0)), Ok(5));
        assert!(i64::from_livr(json!(5.5)).is_err());
    }

    #[test]
    fn reports_errors_at_their_path() {
        let error = String::from_livr(json!(1))
            .unwrap_err()
            .in_field("name")
            .in_item(1)
            .in_field("users");
        assert_eq!(error.to_string(), "expected a string at /users/1/name");
        assert_eq!(
            serde_json::to_value(error.into_errors()).unwrap(),
            json!({"users": [null, {"name": "FORMAT_ERROR"}]})
        );
    }
}
